// Build context for Parse P2 & P3 Reports.
const formItem = $('Upload Form').first();
const form = formItem.json || {};
const templateItem = $input.first();
const templateHtml = templateItem.json?.data || templateItem.json?.body || '';
const categoryName = form['Product Category'] || 'Area Rug';
const dateFolderName = new Date().toISOString().split('T')[0];
const files = Object.entries(formItem.binary || {});

const byName = (pattern) => files.find(([, file]) => pattern.test(String(file.fileName || '')))?.[1] || null;
const p2Binary = byName(/market|trend|project.?2|p2/i) || files[0]?.[1] || null;
const p3Binary = byName(/competitor|project.?3|p3/i) || files.find(([, file]) => file !== p2Binary)?.[1] || files[1]?.[1] || null;

if (!templateHtml) throw new Error('Dashboard template was empty. Check Fetch Template response settings.');
if (!p2Binary || !p3Binary) throw new Error(`Expected two HTML uploads; received ${files.length}.`);

return [{
  json: { categoryName, dateFolderName, templateHtml },
  binary: { p2_binary: p2Binary, p3_binary: p3Binary },
}];

// Parse the two controlled HTML reports without external packages.
const decode = (value = '') => value
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ');
const text = (html = '') => decode(html.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
const section = (html, id) => (html.match(new RegExp(`<section[^>]*id=["']${id}["'][^>]*>([\\s\\S]*?)<\\/section>`, 'i')) || [,''])[1];
const listItems = (html) => [...html.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(m => text(m[1])).filter(Boolean);
const money = (html, label, fallback) => (text(html).match(new RegExp(`${label}[^$]{0,80}(\\$[0-9,.]+)`, 'i')) || [,,])[1] || fallback;
const range = (html, retailer, fallback) => (text(html).match(new RegExp(`Price range\\s+${retailer}\\s+(\\$[0-9,.]+)-(\\$[0-9,.]+)`, 'i')) || []).slice(1,3).join(' - ') || fallback;
const context = $('Extract Form Files').first().json;
const item = $input.first();
const p2Html = (await this.helpers.getBinaryDataBuffer(0, 'p2_binary')).toString('utf8');
const p3Html = (await this.helpers.getBinaryDataBuffer(0, 'p3_binary')).toString('utf8');
if (!p2Html.includes('Market Trend Report') || !p3Html.includes('Competitor Monitoring Report')) throw new Error('The uploaded reports were not recognized as the expected P2 and P3 HTML files.');

const p2Summary = text(section(p2Html, 'executive-summary'));
const marketText = text(section(p2Html, 'market-research'));
const segmentMatches = [...section(p2Html, 'category-deep-dive').matchAll(/<article[^>]*class=["'][^"']*segment[^"']*["'][^>]*>([\s\S]*?)<\/article>/gi)];
const segments = segmentMatches.map((match, index) => {
  const inner = match[1];
  const name = text((inner.match(/<h3[^>]*>([\s\S]*?)<\/h3>/i) || [,''])[1]);
  const description = text((inner.match(/<p[^>]*>([\s\S]*?)<\/p>/i) || [,''])[1]);
  const colors = [...inner.matchAll(/background:\s*(#[0-9a-f]{6})/gi)].map(m => m[1]);
  return { name, tier: index === 0 ? 'Primary' : index === 1 ? 'Growth' : 'Emerging', description, colors };
});
const p2Risks = listItems(section(p2Html, 'risks')).map((value, index) => {
  const [title, ...rest] = value.split(':');
  return { title, description: rest.join(':').trim(), severity: index < 2 ? 'high' : index < 3 ? 'medium' : 'low' };
});
const p2Recommendations = listItems(section(p2Html, 'recommendations')).map(value => ({ title: value.split(':')[0], description: value }));

const comparisonHtml = section(p3Html, 'comparison');
const p3Summary = text(section(p3Html, 'executive-summary'));
const pricingItems = [...section(p3Html, 'pricing').matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)].map(m => text(m[1]));
const actions = listItems(section(p3Html, 'recommendations')).map(value => ({ title: value.split(':')[0], description: value.split(':').slice(1).join(':').trim() || value, priority: 'high' }));
const suppliers = [
  { name: 'Loloi / collaborations', platform: 'Wayfair', knownFor: 'Design-led area rugs and collaborations', priceRange: 'Mid to premium' },
  { name: 'WeWove / RELEANY / Ophanie', platform: 'Amazon', knownFor: 'Washable and value-led listings', priceRange: 'Budget' },
  { name: 'SIXHOME / UERMEI / Mainstays', platform: 'Walmart', knownFor: 'Value and marketplace assortment', priceRange: 'Budget' },
];

const p2Data = {
  summary: p2Summary,
  marketSize2025: (marketText.match(/USD\s*([0-9.]+B)/i) || [,'62.90B'])[1],
  marketSize2033: (marketText.match(/2033[^0-9]*USD\s*([0-9.]+B)/i) || [,'130.62B'])[1],
  marketCagr: (marketText.match(/([0-9.]+% CAGR)/i) || [,'9.59% CAGR'])[1].replace(/ CAGR/i,''),
  segments,
  colors: [...new Set(segments.flatMap(s => s.colors))],
  risks: p2Risks,
  recommendations: p2Recommendations,
  attributeBars: {
    materials: [{label:'Washable performance',width:100,value:'Primary'}, {label:'Natural texture',width:78,value:'Strong'}, {label:'Low pile',width:72,value:'Strong'}],
    sizes: [{label:'5x7',width:92,value:'Core'}, {label:'6x9',width:78,value:'Core'}, {label:'8x10',width:86,value:'Core'}],
    colors: [{label:'Warm neutrals',width:95,value:'Leading'}, {label:'Soft heritage',width:76,value:'Growth'}, {label:'Earth tones',width:81,value:'Growth'}],
    prices: [{label:'Value',width:58,value:'Test'}, {label:'Mid-range',width:90,value:'Priority'}, {label:'Premium',width:44,value:'Explore'}],
  },
};
const p3Data = {
  summary: p3Summary,
  totalProducts: 30,
  retailers: {
    wayfair: { count:10, avg:'$187.73', min:'$67.99', max:'$422.99', budget:2, mid:6, premium:2 },
    amazon: { count:10, avg:'$44.99', min:'$12.99', max:'$73.99', budget:10, mid:0, premium:0 },
    walmart: { count:10, avg:'$30.45', min:'$9.99', max:'$85.49', budget:10, mid:0, premium:0 },
  },
  comparisonHtml,
  opportunities: pricingItems.map(value => ({ title: value.split(':')[0], description: value })),
  quickWins: actions.slice(0,3),
  strategicInitiatives: actions,
  suppliers,
};

return [{ json: { ...context, p2Data, p3Data, parseValidation: { p2Segments: segments.length, p2Risks: p2Risks.length, p2Recommendations: p2Recommendations.length, p3Actions: actions.length, suppliers: suppliers.length } } }];

// Populate every placeholder in the official dashboard template.
const { templateHtml, categoryName, dateFolderName, p2Data, p3Data } = $input.first().json;
const esc = (v = '') => String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const title = String(categoryName || 'Area Rug').trim();
let html = templateHtml;
const replace = (key, value = '') => { html = html.split(`{{${key}}}`).join(String(value)); };
const cards = p2Data.segments.map(s => `<article class="segment-card"><h4>${esc(s.name)}</h4><span class="badge badge-info">${esc(s.tier)}</span><p>${esc(s.description)}</p></article>`).join('');
const swatches = p2Data.colors.map(c => `<span class="color-swatch" style="background:${esc(c)}" title="${esc(c)}"></span>`).join('');
const risks = p2Data.risks.map(r => `<div class="risk-card ${esc(r.severity)}"><h4>${esc(r.title)}</h4><p>${esc(r.description)}</p></div>`).join('');
const recs = p2Data.recommendations.map((r,i) => `<div class="rec-item"><div class="rec-number">${i+1}</div><div class="rec-content"><h4>${esc(r.title)}</h4><p>${esc(r.description)}</p></div></div>`).join('');
const actions = p3Data.strategicInitiatives.map((r,i) => `<div class="initiative-card priority-high"><div class="initiative-number">${i+1}</div><div class="initiative-content"><h4>${esc(r.title)}</h4><p>${esc(r.description)}</p></div></div>`).join('');
const suppliers = p3Data.suppliers.map(s => `<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.platform)}</td><td>${esc(s.knownFor)}</td><td>${esc(s.priceRange)}</td><td>-</td></tr>`).join('');
const supplierCards = p3Data.suppliers.map(s => `<div class="supplier-card"><span class="supplier-name">${esc(s.name)}</span><span class="platform">${esc(s.platform)}</span></div>`).join('');
const opportunities = p3Data.opportunities.map(o => `<div class="opportunity-card"><h4>${esc(o.title)}</h4><p>${esc(o.description)}</p></div>`).join('');
const quickWins = p3Data.quickWins.map((w,i) => `<div class="quick-win"><span>${i+1}.&nbsp;</span><strong>${esc(w.title)}</strong><p>${esc(w.description)}</p></div>`).join('');
const bars = values => values.map(b => `<div class="bar-item"><div class="bar-label">${esc(b.label)}</div><div class="bar-track"><div class="bar-fill" style="width:${b.width}%"></div></div><div class="bar-value">${esc(b.value)}</div></div>`).join('');
const r = p3Data.retailers;
const simple = {
  CATEGORY_NAME:title, CATEGORY_TITLE:`${title} Category Dashboard`, REPORT_DATE:dateFolderName, GENERATED_AT:new Date().toLocaleString('en-AU'),
  TOTAL_PRODUCTS:p3Data.totalProducts, AMAZON_PRODUCTS:r.amazon.count, WALMART_PRODUCTS:r.walmart.count, WAYFAIR_PRODUCTS:r.wayfair.count,
  WAYFAIR_AVG_PRICE:r.wayfair.avg, WAYFAIR_MIN_PRICE:r.wayfair.min, WAYFAIR_MAX_PRICE:r.wayfair.max,
  AMAZON_AVG_PRICE:r.amazon.avg, AMAZON_MIN_PRICE:r.amazon.min, AMAZON_MAX_PRICE:r.amazon.max,
  WALMART_AVG_PRICE:r.walmart.avg, WALMART_MIN_PRICE:r.walmart.min, WALMART_MAX_PRICE:r.walmart.max,
  BUDGET_WAYFAIR:r.wayfair.budget, MID_WAYFAIR:r.wayfair.mid, PREMIUM_WAYFAIR:r.wayfair.premium,
  BUDGET_AMAZON:r.amazon.budget, MID_AMAZON:r.amazon.mid, PREMIUM_AMAZON:r.amazon.premium,
  BUDGET_WALMART:r.walmart.budget, MID_WALMART:r.walmart.mid, PREMIUM_WALMART:r.walmart.premium,
  MARKET_SIZE_2025:p2Data.marketSize2025, MARKET_SIZE_2033:p2Data.marketSize2033, MARKET_CAGR:p2Data.marketCagr,
  TARGET_SEGMENT_NAME:p2Data.segments[0]?.name || 'Modern Washable Neutrals', TARGET_SEGMENT_TIER:p2Data.segments[0]?.tier || 'Primary', TARGET_SEGMENT_USE_CASES:'Living room and family room',
  TREND_KEY_INSIGHT:p2Data.summary, COMPETITIVE_KEY_INSIGHT:p3Data.summary,
  SEGMENTS_HTML:cards, COLOR_PALETTE_HTML:swatches, MOODBOARD_HTML:cards,
  RISKS_HTML:risks, HIGH_RISKS:p2Data.risks.filter(x=>x.severity==='high').length, MEDIUM_RISKS:p2Data.risks.filter(x=>x.severity==='medium').length, LOW_RISKS:p2Data.risks.filter(x=>x.severity==='low').length,
  COMPARISON_TABLE_HTML:p3Data.comparisonHtml, PRICE_GAPS_HTML:'<p>Wayfair holds a premium sampled position; controlled access-price tests are recommended.</p>',
  OPPORTUNITIES_HTML:opportunities, QUICK_WINS_HTML:quickWins, STRATEGIC_INITIATIVES_HTML:actions, SUPPLIERS_HTML:suppliers, SUPPLIER_CHIPS_HTML:supplierCards,
  MATERIALS_BARS_HTML:bars(p2Data.attributeBars.materials), SIZES_BARS_HTML:bars(p2Data.attributeBars.sizes), COLORS_BARS_HTML:bars(p2Data.attributeBars.colors), PRICES_BARS_HTML:bars(p2Data.attributeBars.prices),
  DISCOUNT_TIERS_HTML:`<div class="discount-tier"><span>Budget</span><span>W:${r.wayfair.budget} | A:${r.amazon.budget} | Wm:${r.walmart.budget}</span></div>`,
  ALERTS_HTML:risks, TOP_ACTIONS_HTML:quickWins, TREND_RECOMMENDATIONS_HTML:recs,
};
for (const [key,value] of Object.entries(simple)) replace(key,value);
html = html.replace(/\{\{[A-Z0-9_]+\}\}/g, '');
const fileName = `${title.replace(/\s+/g,'_')}_Dashboard_${dateFolderName}.html`;
const remainingPlaceholders = (html.match(/\{\{/g) || []).length;
if (!html.includes('</html>') || remainingPlaceholders) throw new Error(`Dashboard validation failed; remaining placeholders: ${remainingPlaceholders}`);
return [{ json: { html, fileName, categoryName:title, dateFolderName, validation:{ remainingPlaceholders, htmlLength:html.length, sectionsPopulated:12 } } }];

// Prepare the complete dashboard as a downloadable HTML binary.
const { html, fileName, validation } = $input.first().json;
const buffer = Buffer.from(html, 'utf8');
return [{
  json: { fileName, validation },
  binary: { data: { data: buffer.toString('base64'), mimeType: 'text/html', fileName, fileExtension: 'html' } },
}];
